import unittest
import lib_06fa35ee as m


class Hidden(unittest.TestCase):
    def test_behavior(self):
        chain = ['1.0.0-alpha', '1.0.0-alpha.1', '1.0.0-alpha.beta', '1.0.0-beta', '1.0.0-beta.2', '1.0.0-beta.11', '1.0.0-rc.1', '1.0.0', '1.0.1', '1.2.0', '1.10.0', '2.0.0']
        for i, a in enumerate(chain):
            for j, b in enumerate(chain):
                self.assertEqual(m.compare(a, b), (i > j) - (i < j), (a, b))
        for a, b, want in [('8.1.4-alpha', '2.1.7', 1), ('4.0.8-alpha', '4.0.8-alpha+build.5', 0), ('12.2.4-x.7', '12.2.4-x.7+build.5', 0), ('8.2.11-x.7', '0.3.6-beta', 1), ('5.4.5-alpha', '3.3.0-rc.10', 1), ('9.0.8-alpha', '10.0.4-rc.10', -1), ('1.12.6-rc.1', '4.8.11', -1), ('10.9.10-alpha', '3.4.12-beta', 1), ('1.2.4-2', '1.2.4-beta', -1), ('2.7.0-x.7', '0.8.0-rc.10', 1), ('3.5.11', '6.12.8-11', -1), ('2.8.8-2', '12.11.0', -1), ('1.12.5-2', '1.12.5-2+build.5', 0), ('2.5.5-rc.1', '12.9.3-rc.10', -1), ('9.0.3-2', '1.12.4-beta', 1), ('0.0.4-2', '4.0.6-beta', -1), ('12.1.8', '0.5.10', 1), ('1.9.5-rc.1', '7.12.8-rc.10', -1), ('2.12.7-rc.1', '7.9.6', -1), ('2.4.8', '2.12.8-beta', -1), ('7.7.9', '3.10.10', 1), ('7.7.2-x.7', '2.5.9', 1), ('10.0.0-x.7', '4.12.8-beta', 1), ('8.1.11-2', '3.1.4-11', 1), ('0.9.0-alpha', '0.9.0-alpha+build.5', 0), ('10.9.5-rc.1', '5.11.10-beta', 1), ('9.1.3', '12.6.11-rc.10', -1), ('8.9.7-rc.1', '11.3.12', -1), ('2.4.10-rc.1', '5.1.1', -1), ('9.5.2', '9.5.2+build.5', 0), ('2.4.2-alpha', '9.7.5-rc.10', -1), ('2.3.6-alpha', '8.10.7-beta', -1), ('9.9.7-2', '9.9.7-2+build.5', 0), ('5.7.7', '5.7.7+build.5', 0), ('10.5.3', '10.5.3+build.5', 0), ('5.7.9-alpha', '11.6.5-beta', -1), ('10.5.8-alpha', '2.8.9', 1), ('0.10.12', '3.4.5-beta', -1), ('6.11.3-x.7', '0.11.10-beta', 1), ('5.4.8', '5.7.10', -1), ('10.8.5-x.7', '11.12.8', -1), ('6.12.4-rc.1', '4.3.1', 1), ('4.3.9-rc.1', '12.6.5-beta', -1), ('9.11.10', '1.4.4-11', 1), ('3.0.5-rc.1', '8.11.1-11', -1), ('2.9.3', '2.9.3+build.5', 0), ('2.2.8-x.7', '12.1.6-beta', -1), ('5.1.11-x.7', '7.4.2', -1), ('4.11.2-2', '7.5.3-beta', -1), ('11.0.5-x.7', '0.2.0', 1), ('7.2.11-x.7', '11.9.12-11', -1), ('0.8.10-alpha', '9.7.1-11', -1), ('5.8.6-rc.1', '4.12.7', 1), ('1.9.3-alpha', '3.2.1', -1), ('10.12.12-x.7', '10.12.12-x.7+build.5', 0), ('6.3.5-2', '1.5.12-beta', 1), ('4.6.1-x.7', '10.4.8-rc.10', -1), ('11.3.4', '12.10.10', -1), ('4.2.3-alpha', '0.12.5', 1), ('8.2.4-rc.1', '6.3.12', 1)]:
            self.assertEqual(m.compare(a, b), want, (a, b))
        for bad in ['1.0', '01.0.0', '1.0.0-', '1.0.0-01', 'v1.0.0', '', '1.0.0+']:
            with self.assertRaises(ValueError):
                m.compare(bad, '1.0.0')


if __name__ == "__main__":
    unittest.main()
